from content.authoring import E, J, L, P, Q, R, T
from content.units.input_text import SCANNER

BRANCH = J('Scanner in = new Scanner(System.in);\nint score = in.nextInt();\nif (score < 0 || score > 100) {\n    System.out.println("Invalid");\n} else if (score >= 80) {\n    System.out.println("High");\n} else if (score >= 50) {\n    System.out.println("Pass");\n} else {\n    System.out.println("Retry");\n}', SCANNER)
EQUALITY = J('Scanner in = new Scanner(System.in);\nString choice = in.nextLine().trim();\nif (choice.equals("yes")) {\n    System.out.println("Confirmed");\n} else {\n    System.out.println("Not confirmed");\n}', SCANNER)
DIVIDE = J('Scanner in = new Scanner(System.in);\nif (!in.hasNextDouble()) { System.out.println("Invalid number"); return; }\ndouble a = in.nextDouble();\nif (!in.hasNextDouble()) { System.out.println("Invalid number"); return; }\ndouble b = in.nextDouble();\nif (!Double.isFinite(a) || !Double.isFinite(b)) {\n    System.out.println("Invalid number");\n} else if (b == 0.0) {\n    System.out.println("Cannot divide by zero");\n} else {\n    System.out.println(a / b);\n}', SCANNER)
RECOVER = J('Scanner in = new Scanner(System.in);\nif (!in.hasNextLine()) { System.out.println("Invalid count"); return; }\nString text = in.nextLine().trim();\ntry {\n    int count = Integer.parseInt(text);\n    if (count < 0 || count > 1000) {\n        System.out.println("Invalid count");\n    } else {\n        System.out.println("Count: " + count);\n    }\n} catch (NumberFormatException error) {\n    System.out.println("Invalid count");\n}', SCANNER)
MENU = J('Scanner in = new Scanner(System.in);\nString option = in.nextLine().trim();\nswitch (option) {\n    case "1": System.out.println("Add"); break;\n    case "2": System.out.println("List"); break;\n    case "0": System.out.println("Bye"); break;\n    default: System.out.println("Unknown option");\n}', SCANNER)

LESSONS = [
L('if-else-branches', 'Choose Exactly One Branch', 'Order conditions so boundaries and invalid values are deliberate.',
  ['An if executes its body only when its condition is true. An else body executes when that condition is false. An if/else-if/else chain selects the first true branch and skips the remaining branches. Separate if statements are not mutually exclusive.',
   'Put invalid-range checks before categories. Then put the narrow or higher threshold before a broader overlapping one. In the worked score classifier, checking >= 50 before >= 80 would classify high scores as Pass.',
   'Braces group all statements belonging to a branch. Indentation helps the reader but does not replace braces. Include exact threshold cases in your test table, not only convenient middle values. The input contract here supplies an integer token.'],
  ['Trace a mutually exclusive decision chain.', 'Test exact thresholds and invalid ranges.'],
  E(BRANCH, 'High\n', ['85 is inside 0..100.', '85 satisfies >= 80.', 'Later branches are skipped.'], '85\n'),
  Q('With score 50, what is printed?', BRANCH, 'Pass', '50 is valid, below 80, and exactly satisfies the inclusive pass threshold.'),
  R('Why must the high threshold come before the pass threshold in this chain?', 'High values also satisfy the broader pass condition. A chain stops at the first true branch, so the higher threshold must come first.', ['I identify overlapping conditions.', 'I state that only the first true branch runs.', 'I include a threshold test.']),
  P('Classify an integer temperature: below -50 or above 60 → Invalid; below 0 → Freeze; 0 through 29 → Mild; 30 through 60 → Hot. Read one valid integer token.', J('Scanner in = new Scanner(System.in);\nint t = in.nextInt();\nif (t < -50 || t > 60) System.out.println("Invalid");\nelse if (t < 0) System.out.println("Freeze");\nelse if (t < 30) System.out.println("Mild");\nelse System.out.println("Hot");', SCANNER), [T('zero boundary', '0\n', 'Mild\n'), T('hot threshold', '30\n', 'Hot\n'), T('below range', '-51\n', 'Invalid\n'), T('freezing', '-1\n', 'Freeze\n'), T('upper boundary', '60\n', 'Hot\n')], starter=J('Scanner in = new Scanner(System.in);\nint temperature = in.nextInt();\n// Check invalid ranges, then classify.', SCANNER))),
L('comparisons-strings', 'Compare Values & String Contents', 'Use relational operators for numbers and equals for text.',
  ['Numeric <, <=, >, >=, == and != compare values and produce boolean results. Assignment = stores a value; comparison == asks whether two values are equal. These are different operations.',
   'For String text, use equals to compare content. == compares object references. Some literals share a reference, which can make == seem to work accidentally; user-entered text does not make that safe. "yes".equals(choice) is also safe if choice might be null.',
   'Decide whether your input contract is case-sensitive. equals("yes") is case-sensitive; equalsIgnoreCase handles a simple case-insensitive comparison. Neither operation removes spaces, so trim only if your contract permits it.'],
  ['Compare numeric values without assignment.', 'Check String content rather than reference identity.'],
  E(EQUALITY, 'Confirmed\n', ['Trim the line.', 'Compare its content with yes.', 'Select the confirmation branch.'], 'yes\n'),
  Q('The worked comparison is case-sensitive. For input YES, what is printed?', EQUALITY, 'Not confirmed', 'YES and yes differ in case. equals does not normalize them.'),
  R('Why is choice == "yes" not a reliable check for typed input? Give a correct replacement.', '== checks whether both references identify the same String object. Use choice.equals("yes") for matching content, with suitable null handling if needed.', ['I distinguish identity from content.', 'I use equals for a content test.']),
  P('Read a full command line, trim it, and print Open when it equals open ignoring case. Print Unknown otherwise.', J('Scanner in = new Scanner(System.in);\nString command = in.nextLine().trim();\nif (command.equalsIgnoreCase("open")) System.out.println("Open");\nelse System.out.println("Unknown");', SCANNER), [T('case-insensitive content', ' OPEN \n', 'Open\n'), T('different word', 'close\n', 'Unknown\n'), T('blank input', '\n', 'Unknown\n')], starter=J('Scanner in = new Scanner(System.in);\nString command = in.nextLine().trim();\n// Compare its contents, not its reference.', SCANNER))),
L('logical-operators', 'Combine Rules Safely', 'Use AND, OR and NOT, including short-circuit guards.',
  ['a && b is true only if both conditions are true. a || b is true if either is true. !a reverses a boolean value. Parentheses make a multi-part rule explicit; do not rely on a reader memorizing precedence.',
   '&& and || short-circuit: Java can skip the right operand once the result is known. For !text.isEmpty() && text.charAt(0) == \'A\', the first condition prevents invalid character access on empty input.',
   'Translate inclusive and exclusive boundaries into operators before testing. “Age from 12 through 17 and has a pass” means age >= 12 && age <= 17 && hasPass. Test each boundary and one failing condition at a time.'],
  ['Translate a rule into combined boolean conditions.', 'Use short-circuit evaluation to guard an unsafe operation.'],
  E(J('String text = "";\nboolean beginsA = !text.isEmpty() && text.charAt(0) == \'A\';\nSystem.out.println(beginsA);'), 'false\n', ['isEmpty is true.', 'NOT makes the first operand false.', 'charAt is skipped, so no index error occurs.']),
  Q('What is printed?', J('int age = 12;\nboolean hasPass = false;\nSystem.out.println(age >= 12 && age <= 17 && hasPass);'), 'false', 'The age is in range but the required pass condition is false.'),
  R('Explain why !text.isEmpty() && text.charAt(0) == \'A\' is safer than evaluating charAt first.', 'The left check fails for empty text, so && does not evaluate the invalid index access. Reversing the operands loses that protection.', ['I state the left-to-right short-circuit behavior.', 'I identify the unsafe empty-text access.']),
  P('Read an integer age, then a token yes or no for a pass. Print Eligible only for ages 12 through 17 with yes; otherwise print Not eligible. The input supplies valid tokens.', J('Scanner in = new Scanner(System.in);\nint age = in.nextInt();\nString pass = in.next();\nif (age >= 12 && age <= 17 && pass.equals("yes")) System.out.println("Eligible");\nelse System.out.println("Not eligible");', SCANNER), [T('lower boundary', '12 yes\n', 'Eligible\n'), T('upper boundary', '17 yes\n', 'Eligible\n'), T('one rule fails', '14 no\n', 'Not eligible\n'), T('below age', '11 yes\n', 'Not eligible\n')]),
  diagram={'kind':'branch','nodes':['Age >= 12?','Age <= 17?','Pass content is yes?','All true → Eligible','Any false → Not eligible'],'edges':[[0,1],[1,2],[2,3],[0,4],[1,4],[2,4]]}),
L('input-guards', 'Reject Invalid Paths Before Calculating', 'Guard numeric conversion, nonfinite values and a zero divisor.',
  ['A guard handles a condition that prevents valid work. In main, return ends the method and therefore the normal program path. Check numeric token availability before reading. Missing input and a wrong token should receive a clear result, not an uncaught input error.',
   'A parsed double can still be NaN or Infinity. Double.isFinite rejects both. A nonzero divisor must also be checked before division. Do not print a numerical result for a rejected input.',
   'Guard clauses reduce nesting by ending invalid paths early. They are suitable for a one-shot program. A repeated menu will instead report the problem and continue its loop. Do not accidentally return from the entire application when the contract says retry.'],
  ['Reject invalid numeric tokens and nonfinite values.', 'Prevent zero-divisor work with an explicit guard.'],
  E(DIVIDE, '2.5\n', ['Read both guarded operands.', 'Check both are finite.', 'Check divisor is nonzero.', 'Calculate only on the valid path.'], '5 2\n'),
  Q('What does the worked program print for input 5 0?', DIVIDE, 'Cannot divide by zero', 'The divisor guard runs before division.'),
  R('List the checks needed before dividing two supplied doubles, and distinguish stop from retry.', 'Check both tokens are numeric, both values are finite, and the divisor is nonzero. return stops this one-shot main; a retrying program needs a loop rather than unconditional application exit.', ['I guard parsing, finiteness and the divisor.', 'I distinguish ending a run from retrying.']),
  P('Read two numeric tokens and divide. Print Invalid number for missing, nonnumeric or nonfinite values; Cannot divide by zero for a zero divisor; otherwise print the double quotient.', DIVIDE, [T('decimal result', '9 2\n', '4.5\n'), T('zero divisor', '9 0\n', 'Cannot divide by zero\n'), T('bad token', 'nine 2\n', 'Invalid number\n'), T('nonfinite value', 'NaN 2\n', 'Invalid number\n'), T('missing operand', '2\n', 'Invalid number\n')], starter=J('Scanner in = new Scanner(System.in);\n// Guard each numeric read, check finiteness and the divisor, then divide.', SCANNER))),
L('numeric-recovery', 'Convert One Whole Line Safely', 'Parse a strict integer and handle its specific conversion error.',
  ['Whole-line input avoids the leftover-newline problem. Integer.parseInt(text.trim()) converts a whole String to a bounded int. It rejects blank input, letters, decimal spellings and values outside the int range with NumberFormatException.',
   'A try block contains the risky conversion. catch (NumberFormatException error) handles that specific failure and chooses an intentional output. The handler is not a claim that every failure should be ignored. The exceptions stage will deepen error boundaries.',
   'Parsing and business validation are separate. A negative number can parse correctly but violate a nonnegative-count rule. Check the range after parsing. If no line is available, handle end-of-input before calling nextLine.'],
  ['Parse an entire input line without accepting trailing junk.', 'Handle conversion failures separately from an invalid range.'],
  E(RECOVER, 'Count: 5\n', ['Check a line exists.', 'Trim and parse it.', 'Validate 0..1000.', 'Handle only a numeric conversion failure.'], ' 5 \n'),
  Q('What does the example print for input 5x?', RECOVER, 'Invalid count', 'parseInt rejects the whole invalid String; it does not accept an initial numeric prefix.'),
  R('How do parsing and range validation differ for -3 and pear?', '-3 converts to int but fails the nonnegative rule. pear cannot convert and enters the NumberFormatException handler.', ['I identify the successful parse with invalid meaning.', 'I identify the conversion failure and specific catch.']),
  P('Read one line as a seat count. Accept 0 through 1000 and print Seats: followed by the count; otherwise print Invalid seats. Reject missing, blank, decimal, trailing-junk and overflow input.', J(RECOVER.split('    public static void main(String[] args) {\n',1)[1].rsplit('\n    }',1)[0].replace('Invalid count','Invalid seats').replace('Count: ','Seats: '), SCANNER), [T('normal', '12\n', 'Seats: 12\n'), T('zero', '0\n', 'Seats: 0\n'), T('bad text', '12x\n', 'Invalid seats\n'), T('overflow', '999999999999999999\n', 'Invalid seats\n'), T('negative', '-1\n', 'Invalid seats\n'), T('EOF', '', 'Invalid seats\n')], starter=J('Scanner in = new Scanner(System.in);\n// Check a line exists. Parse in try/catch, then validate the count range.', SCANNER))),
L('switch-selection', 'Route a Menu Command', 'Select one labeled option and handle unknown commands.',
  ['A switch routes a value to a matching case label. Traditional switch statements need break to stop fall-through after a case. default handles unmatched values. Use switch for discrete commands; use if/else for ranges.',
   'Reading a menu choice as a String avoids a numeric parse just to distinguish labels such as 1, 2 and 0. Trim surrounding spaces when the command contract allows them. An empty or unfamiliar option takes default.',
   'This lesson routes one command. It does not yet make a repeated menu. The repetition stage will surround this dispatch with a loop and distinguish a recoverable unknown command from an intentional exit.'],
  ['Route a discrete option with switch.', 'Prevent accidental fall-through and handle default.'],
  E(MENU, 'List\n', ['Read one command.', 'Match case 2.', 'Print List and break.'], '2\n'),
  Q('What does the example print for input 9?', MENU, 'Unknown option', 'No case matches 9, so default executes.'),
  R('Why does a traditional switch case often need break, and when is if/else preferable?', 'Without break, execution can fall through to later statements. Use if/else for interval comparisons such as scores >= 80, rather than enumerating many labels.', ['I explain fall-through rather than claiming every switch automatically stops.', 'I distinguish a command label from a numeric range.']),
  P('Read one command: a → Added, l → Listed, q → Bye; any other trimmed String → Unknown. Use a traditional switch with breaks.', J('Scanner in = new Scanner(System.in);\nString option = in.nextLine().trim();\nswitch (option) {\n    case "a": System.out.println("Added"); break;\n    case "l": System.out.println("Listed"); break;\n    case "q": System.out.println("Bye"); break;\n    default: System.out.println("Unknown");\n}', SCANNER), [T('add', 'a\n', 'Added\n'), T('list', ' l \n', 'Listed\n'), T('exit command', 'q\n', 'Bye\n'), T('unknown', 'x\n', 'Unknown\n')]),
  diagram={'kind':'branch','nodes':['Trim command','a → Added','l → Listed','q → Bye','default → Unknown'],'edges':[[0,1],[0,2],[0,3],[0,4]]}),
L('ternary-operator', 'Optional: a Small Conditional Expression', 'Use a ternary expression only when it improves clarity.',
  ['condition ? valueIfTrue : valueIfFalse chooses an expression value. It is not a replacement for every if statement. Keep both choices simple and compatible with the surrounding type.',
   'Avoid nested ternaries while learning. A multi-step action or complicated validation is clearer as an if/else block. This lesson is optional; completing it is not a prerequisite for the core console-program route.'],
  ['Read the two choices of a conditional expression.', 'Prefer a normal branch for multi-step work.'],
  E(J('int count = 1;\nString label = count == 1 ? "ticket" : "tickets";\nSystem.out.println(label);'), 'ticket\n', ['Test count == 1.', 'Choose the singular String.', 'Print the selected value.']),
  Q('What is printed?', J('int count = 0;\nSystem.out.println(count == 1 ? "ticket" : "tickets");'), 'tickets', 'Zero does not satisfy count == 1, so the second expression is selected.'),
  R('When would you reject a ternary expression in favor of if/else?', 'When the paths have multiple statements or nested conditions that obscure intent. Readability is more important than saving one line.', ['I restrict ternary to a simple expression choice.', 'I choose clear branches for multi-step work.']),
  P('Read one valid integer count and print item for 1 or items otherwise, using a ternary expression.', J('Scanner in = new Scanner(System.in);\nint count = in.nextInt();\nSystem.out.println(count == 1 ? "item" : "items");', SCANNER), [T('singular', '1\n', 'item\n'), T('zero plural', '0\n', 'items\n'), T('many plural', '3\n', 'items\n')]), optional=True),
]
